SELECT CASE WHEN p.brand IN ('Globex', 'Umbrella') THEN 'core' ELSE 'other' END AS brand_group, SUM(ss.revenue) AS total_revenue, ROUND(STDDEV(ss.revenue), 2) AS stddev_revenue FROM store_sales ss JOIN stores s ON ss.store_id = s.id JOIN products p ON ss.product_id = p.id GROUP BY CASE WHEN p.brand IN ('Globex', 'Umbrella') THEN 'core' ELSE 'other' END ORDER BY brand_group DESC, stddev_revenue DESC LIMIT 1
